const API_URL = process.env.NEXT_PUBLIC_API_URL || "https://api.orvoxai.com";

export const api = {
  // Teams
  async getTeamGroups() {
    const res = await fetch(`${API_URL}/api/teams/groups`);
    return res.json();
  },

  async getTeamMemberBySlug(slug: string) {
    const res = await fetch(`${API_URL}/api/teams/members/slug/${slug}`);
    return res.json();
  },

  // Projects
  async getProjects(status?: string) {
    const url = status ? `${API_URL}/api/projects?status=${status}` : `${API_URL}/api/projects`;
    const res = await fetch(url);
    return res.json();
  },

  async getProjectBySlug(slug: string) {
    const res = await fetch(`${API_URL}/api/projects/slug/${slug}`);
    return res.json();
  },

  // Services
  async getServices() {
    const res = await fetch(`${API_URL}/api/services`);
    return res.json();
  },

  // Pricing
  async getPricingPlans() {
    const res = await fetch(`${API_URL}/api/pricing`);
    return res.json();
  },

  // Stats
  async getStats() {
    const res = await fetch(`${API_URL}/api/stats`);
    return res.json();
  },

  // Testimonials
  async getTestimonials() {
    const res = await fetch(`${API_URL}/api/testimonials`);
    return res.json();
  },

  // About
  async getAboutContent() {
    const res = await fetch(`${API_URL}/api/about`);
    return res.json();
  },
};

